class ExecutionsError(Exception):
    def __init__(self, errors, **kwargs):
        super(ExecutionsError, self).__init__(**kwargs)
        self.errors = errors

    def __str__(self):
        return "\n".join(
            "command={command!r}, {error}".format(
                command=command,
                error=error)
            for command, error in self.errors.items())

    def __repr__(self):
        return "ExecutionsError(errors={{{errors}}})".format(
            errors=", ".join(
                "{0!r}: {1!r}".format(*item)
                for item in self.errors.items()))
